<script lang="ts">
  import {onMount} from 'svelte';
  import {call,native} from '../lib/api';
  import {t,locale,formatNumber,formatDate} from '../lib/i18n';
  import {parseSocial,parseDevelopment,hobbyLabels,sceneLabels,scenePhases,routineTime,routineMinute,type SocialSnapshot,type Development,type SceneKind,type HobbyKind} from '../lib/social-experience';
  let {botId,bots,active,disabled=false,onDirtyChange,onBusyChange}:{botId:string;bots:{id:string;name:string}[];active:boolean;disabled?:boolean;onDirtyChange?:(dirty:boolean)=>void;onBusyChange?:(busy:boolean)=>void}=$props();
  let state=$state<SocialSnapshot>(),draft=$state<Development>(),pending=$state(false),error=$state(''),otherId=$state(''),kind=$state<SceneKind>('greeting'),publicOnly=$state(false),confirmReset=$state<'memories'|'development'|null>(null);
  let alive=false,epoch=0,reading=false;
  const uid=$props.id();
  const dirty=$derived(!!draft&&!!state&&JSON.stringify(draft)!==JSON.stringify(state.development));
  $effect(()=>{onDirtyChange?.(dirty);});$effect(()=>{onBusyChange?.(pending);});
  export async function saveDraft(){await save();}
  export function discardDraft(){if(state)draft=structuredClone(state.development);}
  const others=$derived(bots.filter(b=>b.id!==botId));
  const memories=$derived((state?.memories??[]).filter(m=>!publicOnly||m.shared));
  function name(id:string){return bots.find(b=>b.id===id)?.name??$t('Entfernte Figur');}
  async function refresh(){if(reading)return;const id=botId,token=++epoch;reading=true;try{const value=parseSocial(await call('get_social_snapshot',{botId:id}),id);if(alive&&botId===id&&token===epoch){state=value;draft=structuredClone(value.development);error='';}}catch{if(alive&&token===epoch)error='Die sozialen Daten sind derzeit nicht verfügbar.';}finally{reading=false;}}
  $effect(()=>{botId;if(alive){++epoch;state=undefined;draft=undefined;otherId='';confirmReset=null;void refresh();}});
  async function action(command:string,args:Record<string,unknown>={}){if(pending||disabled)return;const id=botId;pending=true;error='';try{await call(command,{botId:id,...args});if(alive&&botId===id){confirmReset=null;await refresh();}}catch{if(alive&&botId===id)error='Die soziale Anfrage wurde nicht bestätigt. Bitte neu laden.';}finally{if(alive)pending=false;}}
  async function save(){if(!state||!draft)return;try{const development=parseDevelopment(draft);await action('set_social_development',{expectedRevision:state.revision,development});}catch{error='Die sozialen Vorlieben sind ungültig.';}}
  async function discardGoal(){if(draft?.goal){draft.goal={...draft.goal,status:'discarded'};await save();}}
  function addRoutine(){if(!draft||draft.routines.length>=8)return;draft={...draft,routines:[...draft.routines,{startMinute:540,endMinute:600,kind:'play',weight:300}]};}
  function setTime(index:number,key:'startMinute'|'endMinute',value:string){if(!draft)return;try{draft.routines[index][key]=routineMinute(value);error='';}catch{error='Die sozialen Vorlieben sind ungültig.';}}
  onMount(()=>{alive=true;void refresh();const timer=setInterval(()=>{if(!pending&&!dirty&&document.visibilityState==='visible')void refresh();},5000);return()=>{alive=false;++epoch;onDirtyChange?.(false);onBusyChange?.(false);clearInterval(timer);};});
</script>
<section class="settings-panel social" aria-labelledby={`${uid}-title`}><header><div><p class="eyebrow">{$t('Gemeinsam leben')}</p><h2 id={`${uid}-title`}>{$t('Beziehungen & Entwicklung')}</h2></div><button class="text-link" disabled={pending||dirty||disabled} onclick={refresh}>{$t('Neu laden')}</button></header>
  <p class="note">{$t('Einladungen dürfen abgelehnt werden. Beziehungen und Fortschritt entstehen aus bestätigten gemeinsamen Aktivitäten.')}</p>{#if error}<p class="error" role="alert">{$t(error)}</p>{/if}
  {#if state&&draft}<div class="invite"><label>{$t('Andere Figur')}<select bind:value={otherId}><option value="">{$t('Figur auswählen')}</option>{#each others as bot}<option value={bot.id}>{bot.name}</option>{/each}</select></label><label>{$t('Gemeinsame Aktivität')}<select bind:value={kind}>{#each Object.entries(sceneLabels) as [value,label]}<option value={value}>{$t(label)}</option>{/each}</select></label><button class="button secondary" disabled={!native||!active||!otherId||pending||disabled} onclick={()=>action('invite_social_scene',{otherId,kind})}>{$t('Einladung senden')}</button></div>
    <ul class="scenes">{#each state.scenes.slice(0,8) as scene(scene.id)}<li><div><strong>{$t(sceneLabels[scene.kind])}</strong> · {$t(scenePhases[scene.phase])}<small>{scene.participants.map(name).join(' + ')}</small>{#if scene.reason}<small>{$t(({declined:'Einladung abgelehnt',timeout:'Wartezeit abgelaufen',unavailable:'Teilnehmer oder Platz nicht verfügbar',operator:'Vom Betreiber beendet',restart:'Beim Neustart beendet'} as const)[scene.reason])}</small>{/if}</div><div class="buttons">{#if scene.phase==='invitation'&&scene.inviterId!==botId}<button class="button secondary" disabled={pending||disabled} onclick={()=>action('respond_social_invitation',{invitationId:scene.id,accept:true})}>{$t('Annehmen')}</button><button class="text-link" disabled={pending||disabled} onclick={()=>action('respond_social_invitation',{invitationId:scene.id,accept:false})}>{$t('Ablehnen')}</button>{/if}{#if !['completed','cancelled','declined'].includes(scene.phase)}<button class="text-link" disabled={pending||disabled} onclick={()=>action('cancel_social_scene',{sceneId:scene.id})}>{$t('Abbrechen')}</button>{/if}</div></li>{/each}</ul>
    <details><summary>{$t('Beziehungen ansehen')}</summary>{#if !state.relationships.length}<p class="note">{$t('Noch keine gemeinsamen Erfahrungen.')}</p>{/if}{#each state.relationships as relationship}<div class="relationship"><strong>{name(relationship.otherId)}</strong><span>{$t('Vertrautheit')}: {formatNumber(relationship.familiarity/100,$locale)}%</span><span>{$t('Zuneigung')}: {formatNumber(relationship.affection/100,$locale)}</span></div>{/each}</details>
    <details><summary>{$t('Persönliche Vorlieben & Routinen')}</summary><p class="note">{$t('Vorlieben beeinflussen Entscheidungen weich. Selbstpflege, verfügbare Plätze und Stop bleiben vorrangig.')}</p><fieldset disabled={pending||disabled}><div class="traits">{#each [['initiative','Eigeninitiative'],['sociability','Geselligkeit'],['patience','Geduld'],['restPreference','Ruhebedürfnis']] as [key,label]}<label>{$t(label)}<input type="range" min="0" max="1000" step="10" bind:value={draft.traits[key as keyof Development['traits']]}/></label>{/each}{#each Object.entries(hobbyLabels) as [key,label]}<label>{$t(label)}<input type="range" min="0" max="1000" step="10" bind:value={draft.interests[key as HobbyKind]}/></label>{/each}</div><div class="routines">{#each draft.routines as routine,index}<div><input aria-label={$t('Beginn der Routine')} type="time" value={routineTime(routine.startMinute)} onchange={e=>setTime(index,'startMinute',e.currentTarget.value)}/><span>–</span><input aria-label={$t('Ende der Routine')} type="time" value={routineTime(routine.endMinute)} onchange={e=>setTime(index,'endMinute',e.currentTarget.value)}/><select aria-label={$t('Aktivität der Routine')} bind:value={routine.kind}>{#each Object.entries(hobbyLabels) as [value,label]}<option value={value}>{$t(label)}</option>{/each}</select><button class="text-link" onclick={()=>draft&&(draft={...draft,routines:draft.routines.filter((_,i)=>i!==index)})}>{$t('Entfernen')}</button></div>{/each}<button class="text-link" disabled={draft.routines.length>=8} onclick={addRoutine}>{$t('Weiche Routine hinzufügen')}</button></div></fieldset><button class="button primary" disabled={!dirty||pending||disabled} onclick={save}>{$t('Vorlieben speichern')}</button></details>
    <details><summary>{$t('Hobbys & eigenes Ziel')}</summary>{#each state.development.hobbies as hobby}<div class="hobby"><span>{$t(hobbyLabels[hobby.kind])}</span><progress aria-label={$t(hobbyLabels[hobby.kind])} value={hobby.experience} max="10000"></progress><span>{formatNumber(hobby.experience/100,$locale)}%</span></div>{/each}{#if draft.goal}<p class="note">{$t(hobbyLabels[draft.goal.kind])}: {formatNumber(draft.goal.progress,$locale)}/{formatNumber(draft.goal.target,$locale)} · {$t(({active:'Aktiv',paused:'Pausiert',achieved:'Erreicht',discarded:'Verworfen'} as const)[draft.goal.status])}</p>{#if !['achieved','discarded'].includes(draft.goal.status)}<button class="text-link" disabled={pending||disabled} onclick={discardGoal}>{$t('Ziel verwerfen')}</button>{/if}{:else}<p class="note">{$t('Noch kein erreichbares eigenes Ziel.')}</p>{/if}<p class="note">{$t('Fortschritt wird ausschließlich nativ bestätigt. Ohne passende Möglichkeit pausiert ein Ziel; Abwesenheit bestraft die Figur nicht.')}</p><button class="text-link" disabled={pending||disabled} onclick={()=>confirmReset='development'}>{$t('Entwicklung zurücksetzen')}</button></details>
    <details><summary>{$t('Soziale Erinnerungen')}</summary><label class="check"><input type="checkbox" bind:checked={publicOnly}/>{$t('Öffentliche Vorschau')}</label><p class="note">{$t('Nur strukturierte eigene Ereignisse, keine Gesprächsprotokolle. Öffentlich wird ein Ereignis erst nach deiner ausdrücklichen Auswahl.')}</p>{#if !memories.length}<p class="note">{$t('Noch keine gemeinsamen Erfahrungen.')}</p>{/if}<ul class="memories">{#each memories.slice(0,30) as memory(memory.eventId)}<li><div><strong>{$t(sceneLabels[memory.kind])}</strong> · {$t(({invited:'Eingeladen',completed:'Abgeschlossen',declined:'Abgelehnt',cancelled:'Abgebrochen'} as const)[memory.outcome])}<small>{memory.participants.map(name).join(' + ')} · {formatDate(memory.atMs,$locale,{dateStyle:'short',timeStyle:'short'})}</small></div>{#if memory.origin==='own'}<label class="check"><input type="checkbox" checked={memory.shared} disabled={pending||disabled} onchange={e=>action('set_social_memory_shared',{eventId:memory.eventId,shared:e.currentTarget.checked})}/>{$t('Explizit öffentlich teilen')}</label>{/if}<button class="text-link" disabled={pending||disabled} onclick={()=>action('delete_social_memory',{eventId:memory.eventId})}>{$t('Löschen')}</button></li>{/each}</ul><button class="text-link" disabled={pending||disabled} onclick={()=>confirmReset='memories'}>{$t('Soziale Erinnerungen zurücksetzen')}</button></details>
    {#if confirmReset}<div class="confirmation"><p>{$t(confirmReset==='memories'?'Alle sozialen Erinnerungen dieser Figur löschen?':'Erworbenen Hobbyfortschritt und eigenes Ziel dieser Figur zurücksetzen?')}</p><button class="button secondary" disabled={pending||disabled} onclick={()=>action(confirmReset==='memories'?'reset_social_memory':'reset_social_development')}>{$t('Zurücksetzen bestätigen')}</button><button class="text-link" disabled={pending} onclick={()=>confirmReset=null}>{$t('Abbrechen')}</button></div>{/if}
  {/if}
</section>
<style>
.social{margin-top:24px}header{display:flex;justify-content:space-between;gap:16px;align-items:center}.eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);margin:0 0 5px}h2{font-size:20px;margin:0}.note{font-size:12px;color:var(--muted);line-height:1.7}.error{font-size:12px;color:var(--danger)}.invite{display:flex;gap:14px;align-items:end;margin:20px 0;flex-wrap:wrap}.invite label{display:grid;gap:6px;flex:1;min-width:160px;font-size:12px}details{border-top:1px solid var(--line);padding:16px 0}summary{cursor:pointer;font-size:12px}.scenes,.memories{list-style:none;padding:0}.scenes li,.memories li{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px;padding:14px 0;border-bottom:1px solid var(--line)}small{display:block;font-size:11px;color:var(--muted);margin-top:5px}.buttons{display:flex;gap:12px}.relationship{display:flex;gap:18px;flex-wrap:wrap;margin:14px 0;font-size:12px}.traits{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:18px 0}.traits label{display:grid;gap:8px;font-size:12px}input[type=range]{padding:0;accent-color:var(--accent)}fieldset{border:0;padding:0;margin:0}.routines>div{display:flex;align-items:center;gap:8px;margin:10px 0;flex-wrap:wrap}.routines input{width:120px}.routines select{width:160px}.hobby{display:grid;grid-template-columns:110px 1fr 50px;align-items:center;gap:12px;font-size:12px;margin:16px 0}progress{width:100%;height:5px;accent-color:var(--accent)}.check{display:flex;gap:8px;align-items:center;font-size:12px}.check input{width:auto;accent-color:var(--accent)}.confirmation{padding:16px;border-left:3px solid var(--warning);background:var(--input-bg);font-size:12px}.confirmation button{margin-right:12px}@media(max-width:680px){.traits{grid-template-columns:1fr}.scenes li,.memories li{align-items:start;flex-direction:column}.hobby{grid-template-columns:90px 1fr 45px}}
</style>
